"""Pydantic schemas for LLM-assisted explainable fake job feature extraction."""
from typing import List, Literal
from pydantic import BaseModel, Field


class ExplainableFlags(BaseModel):
    """Structured explainable flags generated by LLM analysis of unstructured job fields."""

    # 1. Urgency & Pressure Tactics
    urgency_pressure_score: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Score between 0.0 and 1.0 reflecting artificial urgency or high-pressure recruitment tactics.",
    )
    urgency_flags: List[str] = Field(
        default_factory=list,
        description="Specific urgency flags detected (e.g. 'immediate_hire_without_interview', 'limited_slots', 'urgent_call_to_action').",
    )

    # 2. Financial & Payment Anomalies
    financial_anomaly_score: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Score between 0.0 and 1.0 indicating upfront fees, check-cashing, money transfer, or equipment purchase schemes.",
    )
    financial_red_flags: List[str] = Field(
        default_factory=list,
        description="Specific financial red flags (e.g. 'upfront_fee_demanded', 'fake_check_reimbursement', 'cryptocurrency_payment', 'personal_bank_account_usage').",
    )

    # 3. Unrealistic Promises & Compensation
    unrealistic_promises_score: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Score between 0.0 and 1.0 reflecting disproportionate pay relative to skill or unrealistic guarantees.",
    )
    promise_flags: List[str] = Field(
        default_factory=list,
        description="Flags for unrealistic promises (e.g. 'excessive_salary_for_entry_level', 'guaranteed_get_rich_quick', 'unrealistic_bonus').",
    )

    # 4. Suspicious Contact & Communication Channels
    suspicious_contact_score: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Score between 0.0 and 1.0 for informal or evasive communication channels.",
    )
    contact_red_flags: List[str] = Field(
        default_factory=list,
        description="Suspicious contact flags (e.g. 'telegram_or_whatsapp_interview', 'free_webmail_recruiter', 'unverified_short_links').",
    )

    # 5. Vague or Suspicious Role Requirements
    vague_requirements_score: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Score between 0.0 and 1.0 for lack of concrete job duties, qualifications, or skill criteria.",
    )
    requirement_flags: List[str] = Field(
        default_factory=list,
        description="Flags for vague requirements (e.g. 'zero_experience_necessary', 'undefined_daily_tasks', 'generic_buzzwords_only').",
    )

    # 6. Company Legitimacy & Identity Signals
    company_legitimacy_score: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Score between 0.0 (fully legitimate) and 1.0 (highly suspicious / anonymous / evasive company profile).",
    )
    company_red_flags: List[str] = Field(
        default_factory=list,
        description="Company legitimacy flags (e.g. 'missing_company_profile', 'vague_industry', 'impersonation_signals').",
    )

    # 7. Synthesis & Explainability
    overall_fraud_risk_score: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Aggregated fraud risk score between 0.0 (legitimate) and 1.0 (definite fraud/scam).",
    )
    risk_level: Literal["LOW", "MEDIUM", "HIGH", "CRITICAL"] = Field(
        ...,
        description="Categorical risk tier based on overall indicators.",
    )
    explanation_summary: str = Field(
        ...,
        description="Clear, explainable reasoning describing why this job is flagged or considered safe.",
    )
    key_evidence_snippets: List[str] = Field(
        default_factory=list,
        description="Direct quotes or text excerpts extracted from the job posting that provide evidence for flagged anomalies.",
    )
    recommended_action: Literal["APPROVE", "FLAG_FOR_MANUAL_REVIEW", "REJECT_AS_SCAM"] = Field(
        ...,
        description="Operational triage recommendation.",
    )


class EnrichedJobRecord(BaseModel):
    """Complete job record enriched with LLM explainable features and original metadata."""

    job_id: int
    title: str
    location: str = ""
    department: str = ""
    salary_range: str = ""
    company_profile: str = ""
    description: str = ""
    requirements: str = ""
    benefits: str = ""
    telecommuting: int = 0
    has_company_logo: int = 0
    has_questions: int = 0
    employment_type: str = ""
    required_experience: str = ""
    required_education: str = ""
    industry: str = ""
    function: str = ""
    fraudulent: int = 0  # Ground truth if labeled

    # Extracted LLM features
    llm_features: ExplainableFlags
    extraction_method: str = "llm"  # "llm" or "heuristic_fallback"
